<?php
require dirname(__DIR__).'/backend/app/bootstrap.php';$user=require_permission('view_staff');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_permission('manage_users');verify_csrf();try{$name=input('name',120);$code=input('code',40);if($name==='' || !preg_match('/^[a-z0-9-]{2,40}$/',$code))throw new InvalidArgumentException('Enter a department name and a lowercase code using letters, numbers or hyphens.');query('INSERT INTO departments(name,code) VALUES(?,?)',[$name,$code]);flash('Department added.');redirect('departments.php');}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;$error='That department name or code already exists.';}
}
$rows=query("SELECT d.id,d.name,s.team_label,COUNT(s.id) total,COALESCE(SUM(s.employment_status='active'),0) active,COALESCE(SUM(s.employment_status='new'),0) new,COALESCE(SUM(s.employment_status='exited'),0) exited FROM departments d LEFT JOIN staff_directory s ON s.department_id=d.id GROUP BY d.id,d.name,s.team_label ORDER BY d.name,s.team_label")->fetchAll();
page_start('Internal Departments',$user);?><div class="section-head"><div><h2>Where everyone belongs</h2><p class="muted">Current assignments, with transfers preserved in employee history.</p></div></div><?php error_notice($error);?><section class="panel flush"><div class="table-wrap"><table><thead><tr><th>Department</th><th>Team</th><th>All staff</th><th>Active</th><th>New</th><th>Exited</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><a href="staff.php?department_id=<?=$row['id']?>"><?=e($row['name'])?></a></td><td><?=e($row['team_label']??'No team yet')?></td><td><?=(int)$row['total']?></td><td><?=(int)$row['active']?></td><td><?=(int)$row['new']?></td><td><?=(int)$row['exited']?></td></tr><?php endforeach;?></tbody></table></div></section><?php if(user_can('manage_users')):?><section class="panel"><h2>Add department</h2><form method="post" class="filter-grid"><?php csrf_field();?><label>Name<input name="name" maxlength="120" required></label><label>Code<input name="code" pattern="[a-z0-9-]{2,40}" maxlength="40" required placeholder="customer-support"></label><div><button class="button">Add department</button></div></form></section><?php endif;?><?php page_end();
